function(filename) {
    source_path <- file.path(root, "artifacts", "10_figures", "descriptives", filename)
    input_file <- knitr::current_input(dir = TRUE)
    if (!length(input_file) || !nzchar(input_file)) {
        stop("Cannot resolve the source document path for a descriptive figure")
    }
    source_relative_path <- xfun::relative_path(source_path, dirname(input_file), error = FALSE)
    knitr::include_graphics(source_relative_path, rel_path = FALSE, error = FALSE)
}

