function(environment, project_dir) {
    list_file <- environment_value(environment, "QUARTO_USE_FILE_FOR_PROJECT_OUTPUT_FILES")
    if (nzchar(list_file)) {
        list_path <- resolve_path(list_file, project_dir, must_work = TRUE)
        assert_condition(file.exists(list_path) && !dir.exists(list_path), "The Quarto output-list indirection path must be an existing file.")
        outputs <- readLines(list_path, warn = FALSE, encoding = "UTF-8")
    }
    else {
        output_value <- environment_value(environment, "QUARTO_PROJECT_OUTPUT_FILES")
        assert_condition(nzchar(output_value), paste0("QUARTO_PROJECT_OUTPUT_FILES is missing and no output-list ", "indirection file was declared."))
        outputs <- strsplit(output_value, "\n", fixed = TRUE)[[1L]]
    }
    outputs <- sub("\r$", "", outputs)
    assert_condition(length(outputs) > 0L && all(nzchar(outputs)), "The declared Quarto output list must contain only nonempty paths.")
    assert_condition(!anyDuplicated(outputs), "The declared Quarto output list contains duplicate paths.")
    outputs
}

function(path) {
    size <- file.info(path)$size
    readBin(path, what = "raw", n = size)
}

