function(path) {
    connection <- file(path, open = "rb")
    on.exit(close(connection), add = TRUE)
    signature <- readBin(connection, what = "raw", n = 8L)
    expected <- as.raw(c(137, 80, 78, 71, 13, 10, 26, 10))
    if (!identical(signature, expected)) {
        stop("Not a PNG file: ", path, call. = FALSE)
    }
    seek(connection, where = 16L, origin = "start")
    dimensions <- readBin(connection, what = "integer", n = 2L, size = 4L, endian = "big", signed = TRUE)
    c(width_px = dimensions[[1L]], height_px = dimensions[[2L]])
}

function(path) {
    if (!file.exists(path)) {
        stop("Cannot hash missing artifact: ", path, call. = FALSE)
    }
    connection <- file(path, open = "rb")
    on.exit(close(connection), add = TRUE)
    unname(unclass(as.character(openssl::sha256(connection))))
}

function(path, expected_class = NULL) {
    if (!file.exists(path)) {
        stop("Required RDS artifact does not exist: ", path, call. = FALSE)
    }
    object <- readRDS(path)
    if (!is.null(expected_class) && !inherits(object, expected_class)) {
        stop("Artifact ", path, " has class ", paste(class(object), collapse = "/"), "; expected ", expected_class, call. = FALSE)
    }
    object
}

function(metadata) {
    scalar <- vapply(metadata, length, integer(1)) == 1L
    as.data.frame(metadata[scalar], stringsAsFactors = FALSE, optional = TRUE)
}

function(path) {
    if (!is.character(path) || length(path) != 1L || is.na(path) || !nzchar(path)) {
        abort_pipeline("`path` must be one non-empty file path")
    }
    if (!file.exists(path)) {
        abort_pipeline("Site metadata file does not exist: %s", path)
    }
    metadata <- utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE, fileEncoding = "UTF-8")
    validate_site_metadata(metadata, object = "site metadata")
    tibble::as_tibble(metadata)
}

function(manifest, root) {
    if (!"path" %in% names(manifest)) {
        stop("Shared artifact manifest has no `path` column", call. = FALSE)
    }
    paths <- as.character(manifest$path)
    absolute <- grepl("^/", paths)
    paths[!absolute] <- file.path(root, paths[!absolute])
    vapply(paths, normalizePath, character(1), winslash = "/", mustWork = FALSE)
}

